      "path": "src/index.ts",
      "content": "/**
 * dsh-keyboard-manager — node half.
 *
 * Serves the plugin config as JSON on one exact route so the browser half can
 * pull the user's keymap: dsh's web boot mounts client halves through
 * `loader.create({ name })` with no config, and offers no other channel from
 * the loader entry into the page. On profiles without a web server
 * (headless, sdk, acp) there is nothing to register and the browser half
 * simply runs the defaults.
 */
import type { Context } from '@deepseek-ai/cordis'
import { configRoutePath, type KeymapConfig } from './config'

export type { KeymapConfig } from './config'
export { configRoutePath } from './config'

export const name = 'dsh-keyboard-manager'

/** The slice of the webServer service this plugin touches. */
interface WebServerFace {
  register(route: {
    kind: 'exact'
    path: string
    handler: (req: unknown, res: HttpResponse) => void
  }): () => void
}

/** The slice of node's ServerResponse the handler writes through. */
interface HttpResponse {
  setHeader(name: string, value: string): void
  end(body: string): void
}

type HostContext = Context & { get(name: string, strict?: boolean): unknown }

export function apply(ctx: HostContext, config?: KeymapConfig): void {
  const webServer = ctx.get('webServer') as WebServerFace | undefined
  if (!webServer) return
  const body = JSON.stringify(config ?? {})
  ctx.effect(
    () => webServer.register({
      kind: 'exact',
      path: configRoutePath,
      handler: (_req, res) => {
        res.setHeader('Content-Type', 'application/json; charset=utf-8')
        res.setHeader('Cache-Control', 'no-store')
        res.end(body)
      },
    }),
    'keyboard-manager: keymap config route',
  )
}
