export interface KeymapConfig {
  /** Toggle the left sidebar. Defaults to `KeyQ`. */
  sidebar?: string
  /** Toggle the right panel. Defaults to `KeyE`. */
  rightPanel?: string
  /** Toggle Settings. Defaults to `KeyS`. */
  settings?: string
}

/**
 * Exact route the node half serves this plugin's config on. dsh's web boot
 * mounts client halves through `loader.create({ name })` with no config, so
 * the browser half can never receive the plugin config as its `apply` second
 * argument; this HTTP round-trip is the channel that carries it instead.
 */
export const configRoutePath = '/plugin-config/dsh-keyboard-manager'
